# AST critique v4: attack on the AST's structure. Only facts from the AST's own pages; no waiting-list statistics.
BEATS=[
 dict(id='open',gap=0,s=["The American Society of Transplantation had one job when the government unveiled a kidney plan.","Speak for the people waiting.","Instead, it put out a statement.","No target. No deadline. No dollar amount. No role for patients.","Read the statement twice. Then look at who the AST is built for."]),
 dict(id='dues',gap=1.0,s=["Start with the door.","To join, you pay.","Doctoral membership is listed at four hundred eighty-five dollars a year.","Membership is built around people who work in transplantation.","Being a patient is not on the list."]),
 dict(id='industry',gap=1.0,s=["In twenty twenty-five, it opened an affiliate tier for people in industry with a business or strategic interest in transplantation.","Corporate partners are invited to meet with the board every year, to discuss strategy.","Patients get a toolkit, and a link to register as a donor."]),
 dict(id='board',gap=1.2,s=["Now the board.","To be nominated, the society's own criteria have asked for five years of membership in good standing, attendance at its meetings, a record of leadership inside it, and two letters of reference.","Five years of dues and meetings, just to be considered.","No patient. No care partner.","That is not a board patients can reach. It is a board that stays inside the club."]),
 dict(id='network',gap=1.0,s=["Follow the structure.","Dues in. Meetings. Industry at the table.","A network that charges to enter, and listens to the people already inside.","Patients stand at the edge of it, holding a toolkit."]),
 dict(id='quote',gap=1.2,s=["In twenty twenty, this society wrote that for-profit organizations inherently are incentivized to prolong dialysis over offering transplantation.","Those are its words.","Now apply that test to the AST."]),
 dict(id='plan',gap=1.0,s=["The federal plan sets direction. It sets no rules, and no deadlines.","A society that put patients first would demand both.","This one issued a statement."]),
 dict(id='demands',gap=1.0,s=["So here is what we demand.","Patients and care partners on the board, with full votes.","Nominations open to people outside the dues-paying club.","A public account of every dollar it takes from industry.","And dated, public targets for the outcomes it claims to care about."]),
 dict(id='final',gap=1.3,s=["This is not leadership.","It is public relations.","And we have buried too many people to keep pretending otherwise."]),
]
